/// The gallery's example of `RuleOfThirdsGrid`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_guide = match args.choice("guide") {
            "Thirds" => CompositionGuide::Thirds,
            _ => CompositionGuide::GoldenRatio,
        };

        let picture = Canvas::new(|frame, scene| {
            // ravenrs-lint: allow(raw_color) the sky of the stand-in photograph the grid is laid over
            let sky = LinearGradient::vertical(Color::rgb(0.3, 0.45, 0.7), Color::rgb(0.85, 0.6, 0.45));
            scene.push_quad(Quad::new(frame, sky));
        })
        .size(300.0, 170.0);
        {
            let mut it = RuleOfThirdsGrid::new().stage(picture);
            it = it.guide(arg_guide.clone());
            it
        }
    })
}

impl ComponentBook for RuleOfThirdsGrid {
    fn book() -> Meta {
        Meta::new("Media/RuleOfThirdsGrid", render)
            .summary("Composition lines over a picture: thirds, divisions, squares or the golden ratio.")
            .arg(ArgType::choice("guide", &["Thirds", "GoldenRatio"], "GoldenRatio"))
            .story("Example", Args::new())
            .story("Guide: Thirds", Args::new().with("guide", ArgValue::choice("Thirds")))
    }
}
